#!/bin/sh
# Hand the approved queue to the press dispatcher.
echo "enqueue press queue at $(date -u +%Y-%m-%dT%H:%M:%SZ)" >> .effects.log

arguments.command:
python3 - <<'EOF'
import itertools, re, subprocess
jobs0=["J-401","J-415","J-402","J-409","J-418","J-407"]
for p in itertools.permutations(jobs0):
    lst=list(p)
    nums=[int(x[2:]) for x in lst]
    if nums==sorted(nums) and len(set(nums))==len(nums):
        if lst.index("J-418")<lst.index("J-402"):
            print("SOLUTION:",lst)
            break
else:
    print("No permutation of the six given jobs satisfies the audit.")
EOF
